namespace FireURQ.Porter.Translation;

public static class CSharpObjectRuntime
{
    public const string Source = """
// <auto-generated />
#nullable enable
namespace FireURQ.Runtime
{
    // Reference-count portion of the Delphi interface contract.
    // QueryInterface is not implemented yet.
    public interface IInterface
    {
        int _AddRef();
        int _Release();
    }

    public class TInterfacedObject : TObject, IInterface
    {
        int IInterface._AddRef() => _AddRef();
        int IInterface._Release() => _Release();

        protected int FRefCount;

        public int RefCount =>
            global::System.Threading.Volatile.Read(ref FRefCount);

        // Delphi also permits protected-member access within its unit.
        // The generated units currently share one C# assembly.
        protected internal int _AddRef()
        {
            return global::System.Threading.Interlocked.Increment(
                ref FRefCount);
        }

        protected internal int _Release()
        {
            int remaining =
                global::System.Threading.Interlocked.Decrement(
                    ref FRefCount);
            if (remaining == 0)
                Destroy();
            return remaining;
        }
    }

    public class TObject
    {
        private int __fireurqDestructorDepth;

        protected global::System.IDisposable __FireUrqEnterDestructor()
        {
            __fireurqDestructorDepth++;
            return new DestructorScope(this);
        }

        public virtual void Destroy()
        {
            using var scope = __FireUrqEnterDestructor();
        }

        public void Free()
        {
            Free(this);
        }

        public static void Free(TObject? value)
        {
            if (value is not null)
                value.Destroy();
        }

        protected virtual void FreeInstance()
        {
            // Managed object storage is reclaimed by the CLR.
            // Descendants release their owned resources in Destroy.
        }

        private sealed class DestructorScope : global::System.IDisposable
        {
            private TObject? owner;

            public DestructorScope(TObject value)
            {
                owner = value;
            }

            public void Dispose()
            {
                TObject? value = owner;
                if (value is null)
                    return;

                owner = null;
                value.__fireurqDestructorDepth--;
                if (value.__fireurqDestructorDepth == 0)
                    value.FreeInstance();
            }
        }
    }
}
""";
}